MapWidget::MapWidget(AirportGraph* graph, QWidget* parent)
    : QWidget(parent), graph(graph)
{
    setMinimumSize(600, 430);
    QByteArray raw = QByteArray::fromBase64(QByteArray(MAP_B64));
    mapImage.loadFromData(raw);

    for (int i = 0; i < (int)graph->airports.size(); i++) {
        auto* btn = new QPushButton(graph->airports[i].code, this);
        btn->setFixedSize(BTN_W, BTN_H);
        btn->setStyleSheet(
            "QPushButton{background:#111111;color:white;border-radius:3px;"
            "font-size:10px;font-weight:bold;border:none;}"
            "QPushButton:hover{background:#333333;}");
        btn->setCursor(Qt::PointingHandCursor);
        int id = i;
        connect(btn, &QPushButton::clicked, [this,id](){ emit airportClicked(id); });
        airportButtons.push_back(btn);
    }
}

QPoint MapWidget::getScreenPos(float relX, float relY) const {
    return { (int)(relX * width()), (int)(relY * height()) };
}

void MapWidget::updateButtonPositions() {
    for (int i = 0; i < (int)graph->airports.size(); i++) {
        QPoint p = getScreenPos(graph->airports[i].mapX, graph->airports[i].mapY);
        airportButtons[i]->move(p.x() - BTN_W/2, p.y() - BTN_H/2);
        airportButtons[i]->raise();
    }
}

void MapWidget::paintEvent(QPaintEvent*) {
    QPainter p(this);
    p.setRenderHint(QPainter::Antialiasing);
    if (!mapImage.isNull()) {
        // 원본 비율 유지하며 꽉 채움 (중심 기준 크롭)
        QPixmap scaled = mapImage.scaled(size(), Qt::KeepAspectRatioByExpanding,
                                         Qt::SmoothTransformation);
        int dx = (scaled.width()  - width())  / 2;
        int dy = (scaled.height() - height()) / 2;
        p.drawPixmap(-dx, -dy, scaled);
    } else {
        p.fillRect(rect(), QColor(40, 114, 181));
    }

    // 노선 (흰색 선)
    p.setPen(QPen(QColor(255,255,255,180), 1));
    for (const Flight& f : graph->flights) {
        p.drawLine(getScreenPos(graph->airports[f.from].mapX, graph->airports[f.from].mapY),
                   getScreenPos(graph->airports[f.to].mapX,   graph->airports[f.to].mapY));
    }
    // 공항 마커
    p.setBrush(QColor(255,255,255,220));
    p.setPen(Qt::NoPen);
    for (const Airport& a : graph->airports) {
        p.drawEllipse(getScreenPos(a.mapX, a.mapY), 4, 4);
    }
}

void MapWidget::resizeEvent(QResizeEvent* e) {
    QWidget::resizeEvent(e);
    updateButtonPositions();
}